AppTranslator::AppTranslator(QObject* parent)
    : QTranslator(parent)
{
}

QString AppTranslator::translate(const char* context,
                                 const char* sourceText,
                                 const char* disambiguation,
                                 int n) const
{
    Q_UNUSED(context);
    Q_UNUSED(disambiguation);
    Q_UNUSED(n);
    const AppLanguage current = language();
    if (!sourceText || current == AppLanguage::Chinese)
        return QString();

    const QString key = QString::fromUtf8(sourceText);
    const Map& map = current == AppLanguage::Russian ? russianMap() : englishMap();
    const auto it = map.constFind(key);
    return it == map.constEnd() ? QString() : it.value();
}
